const state = {
    category: "All",
    questions: [],
    currentIndex: 0,
    score: 0,
    answered: false,
    selectedAnswer: ""
};

const elements = {
    categoryTabs: document.getElementById("categoryTabs"),
    questionCounter: document.getElementById("questionCounter"),
    scoreCounter: document.getElementById("scoreCounter"),
    categoryName: document.getElementById("categoryName"),
    progressBar: document.getElementById("progressBar"),
    questionTag: document.getElementById("questionTag"),
    questionText: document.getElementById("questionText"),
    answerGrid: document.getElementById("answerGrid"),
    feedbackBox: document.getElementById("feedbackBox"),
    restartQuiz: document.getElementById("restartQuiz"),
    nextQuestion: document.getElementById("nextQuestion"),
    resultSummary: document.getElementById("resultSummary"),
    resultCircle: document.getElementById("resultCircle"),
    bestScorePill: document.getElementById("bestScorePill"),
    shareScore: document.getElementById("shareScore")
};

function shuffleArray(items) {
    return [...items].sort(() => Math.random() - 0.5);
}

function getBestScore() {
    return Number(localStorage.getItem("athanasQuizBestScore") || 0);
}

function setBestScore(scorePercent) {
    const best = getBestScore();
    if (scorePercent > best) {
        localStorage.setItem("athanasQuizBestScore", String(scorePercent));
    }
    updateBestScorePill();
}

function updateBestScorePill() {
    elements.bestScorePill.textContent = `Best: ${getBestScore()}%`;
}

function startQuiz(category = state.category) {
    state.category = category;
    const selectedQuestions = category === "All"
        ? questionBank
        : questionBank.filter(item => item.category === category);

    state.questions = shuffleArray(selectedQuestions).slice(0, Math.min(10, selectedQuestions.length));
    state.currentIndex = 0;
    state.score = 0;
    state.answered = false;
    state.selectedAnswer = "";
    elements.resultSummary.textContent = "Answer the questions and your final result will appear here.";
    elements.resultCircle.textContent = "0%";
    elements.nextQuestion.textContent = "Next Question";
    renderQuestion();
}

function renderQuestion() {
    const currentQuestion = state.questions[state.currentIndex];
    state.answered = false;
    state.selectedAnswer = "";

    elements.questionCounter.textContent = `${state.currentIndex + 1} / ${state.questions.length}`;
    elements.scoreCounter.textContent = String(state.score);
    elements.categoryName.textContent = state.category === "All" ? "All Topics" : state.category;
    elements.questionTag.textContent = currentQuestion.category;
    elements.questionText.textContent = currentQuestion.question;
    elements.feedbackBox.className = "feedback-box";
    elements.feedbackBox.textContent = "";
    elements.progressBar.style.width = `${(state.currentIndex / state.questions.length) * 100}%`;
    elements.nextQuestion.disabled = true;

    elements.answerGrid.innerHTML = "";
    shuffleArray(currentQuestion.choices).forEach(choice => {
        const button = document.createElement("button");
        button.type = "button";
        button.className = "answer-btn";
        button.textContent = choice;
        button.addEventListener("click", () => selectAnswer(button, choice));
        elements.answerGrid.appendChild(button);
    });
}

function selectAnswer(button, choice) {
    if (state.answered) return;

    const currentQuestion = state.questions[state.currentIndex];
    const isCorrect = choice === currentQuestion.answer;
    state.answered = true;
    state.selectedAnswer = choice;

    if (isCorrect) {
        state.score += 1;
        elements.feedbackBox.className = "feedback-box correct";
        elements.feedbackBox.innerHTML = `<strong>Correct — from confusion to clarity!</strong> ${currentQuestion.explanation}`;
    } else {
        elements.feedbackBox.className = "feedback-box wrong";
        elements.feedbackBox.innerHTML = `<strong>Good try — mistakes teach.</strong> The correct answer is <strong>${currentQuestion.answer}</strong>. ${currentQuestion.explanation}`;
    }

    [...elements.answerGrid.children].forEach(answerButton => {
        answerButton.disabled = true;
        if (answerButton.textContent === currentQuestion.answer) {
            answerButton.classList.add("correct-answer");
        }
    });

    if (!isCorrect) {
        button.classList.add("wrong-answer");
    }

    elements.scoreCounter.textContent = String(state.score);
    elements.nextQuestion.disabled = false;

    if (state.currentIndex === state.questions.length - 1) {
        elements.nextQuestion.textContent = "See Result";
    }
}

function nextQuestion() {
    if (!state.answered) return;

    if (state.currentIndex < state.questions.length - 1) {
        state.currentIndex += 1;
        renderQuestion();
    } else {
        finishQuiz();
    }
}

function finishQuiz() {
    const percentage = Math.round((state.score / state.questions.length) * 100);
    setBestScore(percentage);
    elements.progressBar.style.width = "100%";
    elements.resultCircle.textContent = `${percentage}%`;

    let message = "Good start. Keep practicing — ICT confidence grows by doing, not by fearing mistakes.";
    if (percentage >= 80) {
        message = "Excellent work! You are building strong ICT confidence — Athanas Inspires style.";
    } else if (percentage >= 50) {
        message = "Nice effort! Review the explanations, try again, and move one step closer to clarity.";
    }

    elements.resultSummary.textContent = `${message} You scored ${state.score} out of ${state.questions.length} in ${state.category === "All" ? "All Topics" : state.category}.`;
    elements.nextQuestion.disabled = true;
    elements.nextQuestion.textContent = "Quiz Complete";
}

function shareScore() {
    const percentageText = elements.resultCircle.textContent || "0%";
    const summary = elements.resultSummary.textContent || "I practiced with the Athanas Inspires General ICT Quiz Game.";
    const pageUrl = window.location.href;
    const message = `I practiced with the Athanas Inspires General ICT Quiz Game and scored ${percentageText}! ${summary} Try it here: ${pageUrl}`;
    window.open(`https://wa.me/?text=${encodeURIComponent(message)}`, "_blank", "noopener,noreferrer");
}

elements.categoryTabs.addEventListener("click", event => {
    const tab = event.target.closest(".category-tab");
    if (!tab) return;

    document.querySelectorAll(".category-tab").forEach(item => item.classList.remove("active"));
    tab.classList.add("active");
    startQuiz(tab.dataset.category);
});

elements.restartQuiz.addEventListener("click", () => startQuiz(state.category));
elements.nextQuestion.addEventListener("click", nextQuestion);
elements.shareScore.addEventListener("click", shareScore);

updateBestScorePill();
startQuiz("All");

